// Recorded Infinite Craft recipes provided for reuse by the community project:
// https://github.com/vantezzen/infinite-craft-solver
// Source data: https://icscdn.vantezzen.io/recipes.json
// These are existing recorded outcomes, not generated by this app's AI.
// The dataset is incomplete; an unrecorded pair is not the same as a failed pair.
const DATA_URL='https://icscdn.vantezzen.io/recipes.json';
const lookup=new Map();
const knownWords=new Set();
const emojiFallback='✨';
const key=(a,b)=>[String(a).trim().toLocaleLowerCase('en'),String(b).trim().toLocaleLowerCase('en')].sort().join('|');
let loadPromise=null,lastError=null,loadedAt=null,sourceCount=0,uniqueItems=0,discarded=0;
const acceptable=name=>typeof name==='string'&&name.length>=2&&name.length<=55&&
 /^[A-Za-z0-9][A-Za-z0-9 '&!. -]*$/.test(name)&&!/^Nothing$|^undefined$|^A\+B$/i.test(name);
export const communityKnownCombination=(a,b)=>lookup.get(key(a,b))||null;
export const communityCatalog=()=>({recipes:[...lookup].map(([pair,value])=>[...pair.split('|'),value.word]),words:[...knownWords]});
export const communityHasWord=word=>!loadedAt||knownWords.has(String(word).trim().toLowerCase());
export const communityRecipeStats=()=>({
 communityRecipes:lookup.size,
 communityLoaded:loadedAt!==null,
 communityLoading:loadPromise!==null,
 communitySourceRecipes:sourceCount,
 communityElements:uniqueItems,
 communityDiscarded:discarded,
 communityLoadedAt:loadedAt,
 communityError:lastError
});
export function loadCommunityRecipes(){
 if(loadPromise||loadedAt||process.env.DISABLE_COMMUNITY_RECIPES==='1')return loadPromise||Promise.resolve(lookup.size);
 loadPromise=(async()=>{
  let controller;
  try{
   controller=new AbortController();
   const timeout=setTimeout(()=>controller.abort(),30000);
   let response;
   try{response=await fetch(DATA_URL,{signal:controller.signal,headers:{'User-Agent':'InfiniteRace/1.0 (+public community dataset import)'}})}
   finally{clearTimeout(timeout)}
   if(!response.ok)throw Error('Community dataset HTTP '+response.status);
   const data=await response.json();
   if(!Array.isArray(data.items)||!Array.isArray(data.recipes))throw Error('Unexpected dataset format');
   // Refuse unexpectedly large payloads or corrupt data.
   if(data.recipes.length>2000000||data.items.length>2000000)throw Error('Dataset is unexpectedly large');
   const items=data.items,records=data.recipes;
   uniqueItems=items.length;sourceCount=records.length;
   for(const item of items)if(typeof item==='string')knownWords.add(item.trim().toLowerCase());
   const temp=new Map();
   let skipped=0;
   for(const row of records){
    if(!Array.isArray(row)||row.length!==3){skipped++;continue}
    const [i,j,k]=row;
    const a=items[i],b=items[j],word=items[k];
    if(!acceptable(a)||!acceptable(b)||!acceptable(word)){skipped++;continue}
    // Never accept duplicate/inconsistent results or results that merely repeat an ingredient.
    if(word.toLowerCase()===String(a).toLowerCase()||word.toLowerCase()===String(b).toLowerCase()){skipped++;continue}
    const pair=key(a,b);
    if(!temp.has(pair))temp.set(pair,{word,emoji:emojiFallback});
   }
   if(temp.size<10000)throw Error('Community dataset contained too few usable recipes');
   for(const [pair,recipe] of temp)lookup.set(pair,recipe);
   discarded=skipped;
   loadedAt=new Date().toISOString();lastError=null;
   console.log('Infinite Race community recipes loaded:',lookup.size,'from',sourceCount,'recorded pairs');
   return lookup.size;
  }catch(error){
   lastError=String(error?.message||error).slice(0,150);
   console.warn('Community recipe database unavailable; local recipes still work:',lastError);
   return 0;
  }finally{loadPromise=null}
 })();
 return loadPromise;
}
